package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="society_attendance",uniqueConstraints=@UniqueConstraint(name="uk_attendance_roster_date",columnNames={"roster_assignment_id","attendance_date"})) @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class SocietyAttendance { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="roster_assignment_id",nullable=false) private SocietyRosterAssignment rosterAssignment; @Column(nullable=false) private LocalDate attendanceDate; @Column(nullable=false) private String status; @Column(nullable=false) @Builder.Default private String recordingMethod="SUPERVISOR_ENTRY"; private LocalTime checkIn; private LocalTime checkOut; @Column(length=500) private String notes; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="replacement_agency_worker_id") private SocietyAgencyWorker replacementAgencyWorker; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="recorded_by_user_id",nullable=false) private User recordedBy; @Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now(); @Column(nullable=false) @Builder.Default private LocalDateTime updatedAt=LocalDateTime.now(); @PreUpdate void touch(){updatedAt=LocalDateTime.now();} }
